INSERT INTO `counters` (`counterID`, `heroID`, `counteredByHeroID`, `counterTips`, `teammateHelp`, `goodComps`, `dangerousComps`, `severity`) VALUES
(1, 1, 14, 'Genji can deflect Ana\'s sleep dart and biotic grenade back at her. Keep distance and avoid shooting him head-on when Deflect is active. Pre-aim high ground corners and use sleep dart pre-emptively when you hear him dashing.', 'A Kiriko suzu can cleanse sleep darts from allies. Winston or D.Va can dive Genji off of Ana to peel for her. Brigitte\'s armor and stun shut Genji down completely.', '[\"Winston + Kiriko dive\",\"D.Va + Lucio speed\",\"Reinhardt + Brigitte brawl\"]', '[\"Genji + Nano blade Genji\",\"Double flanker with Tracer\"]', 3),
(2, 1, 43, 'Tracer\'s blinks make landing sleep dart very difficult. Use your sidearm at close range and try to land a sleep dart when she stops to reload or recall. Stay near teammates.', 'Brigitte hard-counters Tracer — her inspire aura and stun force Tracer away. Cassidy\'s magnetic grenade is a reliable Tracer delete.', '[\"Brigitte + Ana poke\",\"Bastion + Orisa hold\"]', '[\"Tracer + Sombra double dive\",\"Tracer + Genji dive\"]', 2),
(3, 1, 40, 'Sombra\'s hack disables Ana\'s entire kit — no sleep dart, no grenade, no ult charge. Stay grouped so teammates can kill a hacked Sombra before she reaches you. Hold sleep dart for when she decloaks.', 'Kiriko teleports to Ana and suzu-cleanses hack instantly. Winston can chase Sombra off high ground. Wrecking Ball can detect Sombra with sensors.', '[\"Kiriko + Ana\",\"Winston dive to punish Sombra\"]', '[\"Sombra + Reaper deathmatch flanks\",\"Sombra + Zarya\"]', 3),
(4, 1, 46, 'Widowmaker out-ranges Ana and one-shots her easily. Use cover aggressively and never hold the same angle twice. Your sleep dart can punish a scoped widow at medium range.', 'Winston is the classic Widow dive. Echo or Pharah force Widow off her perch. A Hanzo can duel her on her own angles.', '[\"Winston + Lucio dive\",\"Pharah + Mercy poke\"]', '[\"Widowmaker + Ashe poke\",\"Double sniper\"]', 2),
(5, 3, 47, 'Winston leaps directly onto Ashe and his bubble blocks her shots. Move away from high ground when you see a Winston nearby. Use B.O.B. to stall him and try to escape with your shotgun knockback.', 'Roadhog can hook Winston mid-leap. Brigitte\'s stun peels Winston off Ashe. Zenyatta discord orb on Winston makes the dive punishable.', '[\"Orisa + Ashe poke anchor\",\"Roadhog + Ashe\"]', '[\"Winston + Tracer dive\",\"Winston + D.Va double dive\"]', 3),
(6, 3, 31, 'Pharah flies out of Ashe\'s effective hitscan range and punishes stationary positioning. Track her arc and use Dynamite to zone her landing spots. B.O.B. can tag airborne Pharah.', 'Cassidy or Soldier: 76 can out-duel Pharah in the air. Ana\'s sleep dart destroys Pharah. Roadhog hook kills Pharah instantly if she flies low.', '[\"Cassidy + Zenyatta poke\",\"Soldier: 76 + Mercy\"]', '[\"Pharah + Mercy poke\",\"Pharah + Juno air combo\"]', 3),
(7, 3, 33, 'Reaper teleports or wraiths onto Ashe and deletes her in close quarters. Maintain distance and use Dynamite to zone doorways. Never let Reaper walk up freely.', 'Roadhog can hook Reaper before he reaches Ashe. Brigitte stun stops his engage. High-ground tanks like Orisa or Sigma shield Ashe from him.', '[\"Orisa + Ashe hold\",\"Sigma + Ashe long-range\"]', '[\"Reaper + Roadhog brawl\",\"Reaper + Junker Queen brawl\"]', 2),
(8, 4, 40, 'Sombra hack disables Immortality Field, Regen Burst, and Amplification Matrix. Prioritize killing the drone immediately when hacked. Pre-place immortality field before entering a Sombra-known zone.', 'Kiriko suzu cleanses hack on Baptiste instantly. Winston or D.Va can chase Sombra off Baptiste. Wrecking Ball sensor detects invisible Sombra.', '[\"Kiriko + Baptiste\",\"Winston dive to kill Sombra\"]', '[\"Sombra + Reaper brawl dives\",\"Sombra + Zarya counter-dive\"]', 3),
(9, 4, 46, 'Baptiste has large hitbox and is often static while healing — easy Widow target. Use Exo Boots to jump behind cover and reposition. Don\'t hold long sightlines.', 'Winston dive on Widow protects the backline. Echo or Pharah force Widow off angles. D.Va fly-matrix can block sniper shots.', '[\"Orisa + Baptiste poke\",\"D.Va + Baptiste\"]', '[\"Widowmaker + Ashe poke\",\"Double sniper spam\"]', 2),
(10, 4, 14, 'Genji can deflect Baptiste\'s biotic launcher burst back at him. Don\'t spam bullets into Deflect. Immortality Field saves teammates he dives but not Baptiste himself.', 'Brigitte is the best Genji answer — stun and inspire. Kiriko teleport-suzu combo saves Baptiste from burst combos.', '[\"Brigitte + Baptiste\",\"Orisa + Baptiste hold\"]', '[\"Genji + Tracer double flanker\",\"Dive with Sombra\"]', 2),
(11, 5, 31, 'Bastion can\'t angle up to hit Pharah effectively in Sentry mode. Switch to Recon mode to track her or use Artillery ult. Ask a hitscan teammate to handle her.', 'Cassidy, Soldier: 76, or Widowmaker easily punish Pharah. Ana sleep dart drops Pharah out of the sky.', '[\"Orisa shield + Bastion\",\"Reinhardt shield + Bastion\"]', '[\"Pharah + Mercy poke\",\"Pharah + Juno aerial\"]', 3),
(12, 5, 40, 'Sombra hack disables Bastion completely — no abilities, no Sentry mode, no ult. Place yourself near teammates so they can kill the Sombra quickly. Her EMP destroys whole team setups around Bastion.', 'Kiriko suzu cleanses hack instantly. Wrecking Ball sensor detects Sombra. Any tank peeling for Bastion forces Sombra off.', '[\"Orisa + Bastion + Kiriko hold\",\"Reinhardt shield anchor\"]', '[\"Sombra + EMP into Bastion setup\",\"Genji deflect spam into Bastion\"]', 3),
(13, 5, 14, 'Genji can reflect Bastion\'s Sentry mode bullets back at him for an instant kill. Never fire into Deflect. Switch to Recon mode and dodge when Deflect is up.', 'Brigitte hard counters Genji. Widowmaker or Hanzo can duel Genji on angles before he reaches Bastion.', '[\"Brigitte + Bastion brawl\",\"Reinhardt + Bastion + Brigitte\"]', '[\"Genji + Tracer dive\",\"Genji + Ana nano dive\"]', 3),
(14, 6, 31, 'Brigitte has no ranged ability to answer Pharah\'s aerial poke. Shield bash and rocket flail are melee-range only. Stay under cover and ask teammates to handle Pharah while you keep supports alive.', 'Cassidy or Soldier: 76 hard counter Pharah. Ana sleep dart brings Pharah down. Widowmaker one-shots Pharah.', '[\"Orisa + Brigitte hold\",\"Sigma + Brigitte poke\"]', '[\"Pharah + Mercy\",\"Pharah + Juno air dominance\"]', 3),
(15, 6, 33, 'Reaper\'s lifesteal neutralizes Brigitte\'s inspire healing. He can walk through her melee range and outsustain her. Use Shield Bash + Whipshot to interrupt his engage, then disengage.', 'Roadhog hook removes Reaper from the fight. Junkrat mines zone doorways Reaper uses. High-ground holds prevent Reaper flanks.', '[\"Orisa + Brigitte + Ana poke\",\"Bastion + Brigitte hold\"]', '[\"Reaper + Junker Queen brawl\",\"Reaper + Roadhog dive-brawl\"]', 2),
(16, 6, 40, 'Sombra hack disables Shield Bash, Rally, and Repair Pack. A hacked Brigitte is just a slow melee hero. Use whipshot to interrupt Sombra\'s hack cast before it completes.', 'Kiriko suzu cleanses hack. Winston dive deletes Sombra off the support line. D.Va fly matrix can intercept Sombra\'s engage path.', '[\"Kiriko + Brigitte\",\"Reinhardt + Brigitte + Ana\"]', '[\"Sombra + Tracer double flank\",\"Sombra EMP into full dive\"]', 2),
(17, 7, 31, 'Pharah flies out of Cassidy\'s reliable hitscan range. Fan the Hammer does not reach her effectively. Use Magnetic Grenade on Pharah when she flies close to the ground and ask a Soldier or Widow to handle air.', 'Soldier: 76 or Widowmaker take over air duty. Ana sleep dart drops Pharah. D.Va fly matrix blocks Pharah rockets.', '[\"Soldier: 76 + Cassidy hitscan pair\",\"Orisa + Cassidy poke\"]', '[\"Pharah + Mercy domination\",\"Pharah + Juno aerial\"]', 3),
(18, 7, 14, 'Genji deflects Cassidy\'s fan the hammer — avoid shooting during Deflect. Use Magnetic Grenade as a burst tool that ignores deflect. At close range, Cassidy wins the duel if grenade hits.', 'Brigitte hard counters Genji. Kiriko teleport blocks Genji bursts on supports. Any area-denial hero zones out Genji\'s flanks.', '[\"Brigitte + Cassidy\",\"Reinhardt + Cassidy brawl\"]', '[\"Genji + Ana nano blade\",\"Genji + Tracer dive\"]', 2),
(19, 7, 35, 'Roadhog hook-shotgun one-shots Cassidy at close range. Maintain distance, use cover, and pre-aim hook paths. Magnetic Grenade attached to Roadhog right before hook wins the duel.', 'Orisa spear disrupts Roadhog hook. Zarya bubble on Cassidy prevents one-shots. Ana anti-heal grenade cripples Roadhog sustain.', '[\"Orisa + Cassidy\",\"Zarya + Cassidy\"]', '[\"Roadhog + Reaper brawl dive\",\"Roadhog + Junkrat spam\"]', 2),
(20, 10, 50, 'Zarya\'s bubble charges off every matrix-blocked shot and her beam melts D.Va\'s mech. Never use Defense Matrix into a bubbled Zarya. Save matrix for her Graviton Surge. Peel away when her energy is high.', 'Ana anti-grenade counters Zarya sustain. Sombra hacks Zarya\'s bubble away. Ramattra blocks Zarya beam with Nemesis form annihilation.', '[\"Ana + D.Va poke dive\",\"Sombra + D.Va dive\"]', '[\"Zarya + Reaper brawl\",\"Zarya + Graviton + Hanzo combo\"]', 3),
(21, 10, 33, 'Reaper\'s shotguns shred D.Va\'s mech from inside her blind spots. His Wraith lets him escape Defense Matrix. Avoid getting flanked — use Boosters to keep distance when Reaper is close.', 'Roadhog hook catches Reaper. Brigitte stun stops Reaper engage. Ana anti-heal grenade prevents Reaper lifesteal.', '[\"Orisa + D.Va anchor hold\",\"Sigma + D.Va\"]', '[\"Reaper + Roadhog brawl\",\"Reaper + Zarya brawl combo\"]', 3),
(22, 10, 35, 'Roadhog hook drags D.Va out of position and his shotgun burst destroys the mech quickly. Never drift into hook range alone. Boosters can interrupt hook cast if timed perfectly.', 'Orisa spear disrupts Roadhog hook aim. Sombra hacks Roadhog, removing hook. Ana anti-heal grenade stops his tank healing.', '[\"Orisa + D.Va\",\"Sombra + D.Va dive\"]', '[\"Roadhog + Reaper\",\"Roadhog + Junkrat brawl\"]', 2),
(23, 9, 40, 'Sombra hack removes all of Doomfist\'s mobility and mitigation, turning him into a stationary target. Play very cautiously on cooldowns — if hacked mid-combo, you die. Try to punch Sombra before she can cast hack.', 'Kiriko suzu cleanses hack on Doomfist mid-fight. Wrecking Ball sensor spots Sombra. Moira fade repositions Doomfist away from Sombra.', '[\"Kiriko + Doomfist dive\",\"Lucio + Doomfist dive speed\"]', '[\"Sombra + Tracer double hack dive\",\"Sombra + Ana counter-dive\"]', 3),
(24, 9, 6, 'Brigitte\'s Shield Bash interrupts Doomfist combos and her inspire healing counters his mitigation loss. Avoid one-shotting targets near a Brigitte. Her armor pack reduces burst damage.', 'Lucio speedboost lets Doomfist disengage if Brigitte appears. Ana nano boost buffs Doomfist through brawl if needed.', '[\"Lucio + Doomfist speed\",\"Ana + Doomfist nano dive\"]', '[\"Brigitte + Orisa hold\",\"Brigitte + Reinhardt brawl\"]', 3),
(25, 9, 1, 'Ana sleep dart can catch Doomfist mid-air between dashes. Anti-heal grenade cancels his passive HP regeneration from blocking. Her high single-target damage also punishes him in extended fights.', 'Kiriko suzu cleanses anti-grenade when Doomfist has it. Moira orb healing offsets anti-heal. Lucio speedboost helps Doomfist flee Ana sightlines.', '[\"Kiriko + Doomfist\",\"Lucio speed + Doomfist\"]', '[\"Ana + Kiriko anti-dive\",\"Ana + Orisa poke hold\"]', 2),
(26, 11, 31, 'Pharah and Echo compete in air space — Pharah\'s concussive blast and rockets punish Echo when hovering. Avoid hovering near Pharah. Use Focusing Beam on low-HP targets on the ground instead.', 'Ana sleep dart or Cassidy magnetic grenade handles Pharah. Sigma anti-gravity orb disrupts Pharah\'s flight path.', '[\"Echo + Cassidy hitscan pair\",\"Ana + Echo\"]', '[\"Pharah + Mercy poke\",\"Pharah + Juno air duo\"]', 2),
(27, 11, 46, 'Echo has a very large hitbox while flying, making her a prime Widowmaker target. Stay behind cover and use Glide sparingly. Duplicate a Widowmaker to mirror her on the same angle.', 'Winston dive on Widow is ideal. D.Va fly-matrix blocks sniper bullets. Another Widowmaker or Hanzo can duel her.', '[\"Winston + Echo dive\",\"D.Va + Echo\"]', '[\"Widowmaker + Ashe double sniper\",\"Widowmaker + Cassidy hitscan lock\"]', 3),
(28, 11, 35, 'Roadhog hook pulls Echo out of the air and his shotgun burst one-shots her. Don\'t fly low near a Roadhog. Duplicate a Roadhog with Duplicate to win the hook duel.', 'Orisa spear interrupts Roadhog hook. Ana anti-grenade cripples Roadhog self-heal. Zarya bubble saves Echo from a hook kill.', '[\"Orisa + Echo poke\",\"Ana + Echo\"]', '[\"Roadhog + Reaper brawl\",\"Roadhog + Junkrat trap zone\"]', 2),
(29, 14, 6, 'Brigitte\'s Shield Bash stuns Genji mid-dash and her inspire healing counters his burst damage. Play aggressively — she is your hardest counter. Avoid fighting her alone; wait for nano blade and use teammates as distraction.', 'Ana nano boost powers through Brigitte if the fight is unavoidable. Lucio boop can separate Brigitte from the group so Genji can fight others.', '[\"Ana + Genji nano blade\",\"Lucio + Genji dive speed\"]', '[\"Brigitte + Orisa brawl\",\"Brigitte + Reinhardt brawl hold\"]', 3),
(30, 14, 7, 'Cassidy\'s Magnetic Grenade attaches on dash and cannot be deflected reliably. At close range, Fan the Hammer also punishes Genji. Deflect still works against his main shots — use it on fan the hammer.', 'Lucio speed helps Genji disengage from Cassidy. Kiriko suzu cleanses magnetic grenade effect.', '[\"Ana + Genji nano blade dive\",\"Lucio + Genji + Tracer\"]', '[\"Cassidy + Brigitte lockdown\",\"Cassidy + Orisa hold\"]', 2),
(31, 14, 35, 'Roadhog hook can grab Genji mid-dash if aimed predictively. His huge HP and shotgun burst kill Genji before he can react. Deflect the hook if you see it coming — otherwise stay at range.', 'Orisa spear disrupts Roadhog. Lucio speed lets Genji dodge hooks. D.Va matrix can block the hook chain.', '[\"Lucio + Genji speed dive\",\"Kiriko + Genji\"]', '[\"Roadhog + Moira sustain brawl\",\"Roadhog + Reaper brawl\"]', 2),
(32, 15, 46, 'Widowmaker wins the sniper duel — she charges shots faster and has mobility tools Hanzo lacks. Pre-fire angles with Storm Arrow. Use Lunge to dodge her scoped shot and reposition immediately.', 'Winston dives Widow off angles. D.Va fly matrix blocks her shots. Echo duplicate can mirror Widow.', '[\"Hanzo + Orisa poke hold\",\"Hanzo + Sigma long-range\"]', '[\"Widowmaker + Ashe double sniper\",\"Widowmaker + Cassidy poke\"]', 2),
(33, 15, 33, 'Reaper closes distance fast and Hanzo has very low close-range damage before Storm Arrow is loaded. Use Lunge to escape Reaper\'s teleport flank and try to pre-aim teleport landing spots.', 'Roadhog hook intercepts Reaper before he reaches backline. Brigitte stun stops Reaper engage. Orisa fortify+spear combo punishes Reaper approach.', '[\"Orisa + Hanzo poke\",\"Roadhog + Hanzo\"]', '[\"Reaper + Sombra backline dive\",\"Reaper + Zarya brawl\"]', 3),
(34, 15, 10, 'D.Va\'s Defense Matrix eats Hanzo\'s arrows including Storm Arrows and Dragonstrike. Fire at non-matrix angles or use Sonic Arrow to track her position. Avoid ult when matrix is available.', 'Sombra hacks D.Va, removing matrix. Zarya bubble protects Hanzo from D.Va dive. Ana sleep dart prevents D.Va bomb.', '[\"Sigma + Hanzo poke\",\"Orisa + Hanzo hold\"]', '[\"D.Va + Winston double dive\",\"D.Va + Genji dive\"]', 2),
(35, 20, 31, 'Pharah flies above Junkrat\'s grenade arc range completely. You cannot effectively hit her with grenades at high altitude. Use RIP-Tire to track Pharah if she is low, otherwise request a teammate swap.', 'Cassidy, Soldier: 76, or Widowmaker eliminate Pharah. Ana sleep dart grounds her. Hanzo\'s Storm Arrow punishes aerial targets.', '[\"Junkrat + Orisa choke hold\",\"Junkrat + Reinhardt gate\"]', '[\"Pharah + Mercy poke\",\"Pharah + Juno air combo\"]', 3),
(36, 20, 46, 'Widowmaker out-ranges Junkrat completely and can one-shot him easily. Stay behind walls and use indirect angles. Your grenades deny ground approaches but can\'t answer sniper perches.', 'Winston or Wrecking Ball dive Widow off position. D.Va fly-matrix covers Junkrat from sniper fire. Pharah can contest Widow\'s high ground.', '[\"Junkrat + Reinhardt choke hold\",\"Junkrat + Orisa\"]', '[\"Widowmaker + Ashe long range\",\"Double sniper poke\"]', 2),
(37, 20, 10, 'D.Va Defense Matrix erases Junkrat\'s grenades and mines entirely. Focus fire elsewhere while matrix is active. RIP-Tire can be eaten by matrix — time it for when matrix is on cooldown.', 'Sombra hacks D.Va, disabling matrix. Zarya\'s Graviton pulls D.Va into Junkrat mine clusters. Ana sleep dart prevents Self-Destruct.', '[\"Junkrat + Sombra\",\"Junkrat + Zarya Graviton combo\"]', '[\"D.Va + Winston dive eating mines\",\"D.Va + Tracer dive\"]', 3),
(38, 19, 1, 'Ana\'s anti-heal grenade completely shuts down Junker Queen\'s passive wound healing and Commanding Shout sustain. Never fight Ana in the open — close the gap through terrain and use Carnage before she grenade you.', 'Kiriko suzu cleanses anti-heal from Junker Queen instantly. Moira orb healing can partially offset anti-heal. Lucio speed helps JQ engage before grenade lands.', '[\"Kiriko + Junker Queen\",\"Lucio + Junker Queen brawl\"]', '[\"Ana + Brigitte anti-brawl\",\"Ana + Kiriko sustain lock\"]', 3),
(39, 19, 30, 'Orisa\'s Fortify makes her immune to JQ\'s knockback and slow. Her high poke damage and Spear punish JQ\'s aggressive dashes. Engage through flanks and avoid head-on fights with a fortified Orisa.', 'Sombra hacks Orisa, disabling Fortify. Kiriko suzu on JQ removes spear slow. Ana nano boost helps JQ brawl through Orisa.', '[\"Lucio + JQ speed\",\"Kiriko + JQ brawl\"]', '[\"Orisa + Bastion anchor hold\",\"Orisa + Sigma poke\"]', 2),
(40, 19, 35, 'Roadhog out-sustains Junker Queen in a direct brawl due to his self-heal. Hook punishes her engage cooldowns. Use Shout before engaging to maximize HP and try to outflank him.', 'Ana anti-heal grenade on Roadhog negates his Take a Breather. Sombra hack removes hook. Lucio speed lets JQ disengage from a bad brawl.', '[\"Lucio + JQ speed engage\",\"Ana + JQ brawl burst\"]', '[\"Roadhog + Reaper sustain brawl\",\"Roadhog + Moira healing brawl\"]', 2),
(41, 21, 46, 'Juno is a mobile support but Widowmaker can track her through the air since she is predictable while boosting. Stay low and use terrain cover. Ring of Salvation can be cast from behind cover safely.', 'Winston or D.Va dive Widow off angle. Pharah contests Widow\'s high-ground position. Cassidy magnetic grenade on airborne Widow punishes.', '[\"Juno + Pharah aerial poke\",\"Juno + D.Va speed dive\"]', '[\"Widowmaker + Ashe long range poke\",\"Widowmaker + Hanzo double sniper\"]', 2),
(42, 21, 40, 'Sombra hack disables Juno\'s Hyper Ring speed boost and Orbital Ray ult. A hacked Juno loses her mobility and healing output. Pre-place Orbital Ray before entering a Sombra-heavy zone.', 'Kiriko suzu cleanses hack from Juno. Winston dive keeps Sombra off the support line. Wrecking Ball sensor detects Sombra position.', '[\"Kiriko + Juno double support\",\"Winston + Juno dive\"]', '[\"Sombra + Reaper flanks\",\"Sombra + Tracer double dive\"]', 2),
(43, 22, 40, 'Sombra hack disables Kiriko\'s teleport and Suzu — her two core tools. This makes her a stationary healer that is easy to eliminate. Save Suzu for the brief window before getting hacked by throwing it pre-emptively.', 'Wrecking Ball sensor detects Sombra. Winston dive keeps Sombra busy. Brigitte stun stops Sombra before she can hack.', '[\"Wrecking Ball + Kiriko\",\"Winston + Kiriko dive\"]', '[\"Sombra + Tracer double flank\",\"Sombra EMP into full dive\"]', 3),
(44, 22, 7, 'Cassidy\'s Magnetic Grenade bypasses Kiriko\'s Suzu invincibility window and deals good burst to her fragile frame. Avoid clustering with teammates near a Cassidy angle. Teleport away from grenade range.', 'Reinhardt shield covers Kiriko from Cassidy poke. Orisa fortify and spear push Cassidy off angles. Genji can duel Cassidy to relieve pressure.', '[\"Kiriko + Reinhardt brawl\",\"Kiriko + Ana poke\"]', '[\"Cassidy + Brigitte anti-flanker\",\"Cassidy + Orisa hold\"]', 2),
(45, 23, 43, 'Lifeweaver has very slow mobility tools and Tracer easily out-maneuvers him. His Thorn Volley is slow and inaccurate against a blinking Tracer. Petal Platform can be used to deny Tracer ground approach.', 'Brigitte hard counters Tracer. Cassidy magnetic grenade deletes Tracer. Kiriko kunai can pressure Tracer off the support.', '[\"Brigitte + Lifeweaver\",\"Orisa + Lifeweaver anchor\"]', '[\"Tracer + Sombra double flank\",\"Tracer + Genji dive\"]', 3),
(46, 23, 40, 'Sombra hack disables all of Lifeweaver\'s abilities — Pull, Platform, and Rejuvenating Dash. Hacked Lifeweaver is defenseless. Group with teammates so they can kill Sombra off you.', 'Kiriko suzu cleanses hack. Winston dive forces Sombra to disengage. Wrecking Ball sensor reveals Sombra position.', '[\"Kiriko + Lifeweaver double support\",\"Winston + Lifeweaver dive\"]', '[\"Sombra + Reaper backline\",\"Sombra EMP into dive\"]', 3),
(47, 24, 40, 'Sombra hack stops Lucio\'s wallride, boop, and Sound Barrier ult — all critical for his mobility and peel. Try to boop Sombra before hack completes and stay near high walls to maintain some movement options.', 'Kiriko suzu cleanses hack on Lucio. Wrecking Ball sensor detects Sombra. Brigitte can peel Sombra off Lucio with stun.', '[\"Kiriko + Lucio\",\"Brigitte + Lucio brawl speed\"]', '[\"Sombra + Tracer double flank\",\"Sombra EMP + Lucio ult cancel\"]', 2),
(48, 24, 7, 'Cassidy\'s magnetic grenade attaches to Lucio even while wallriding and deals heavy burst. His fan the hammer punishes Lucio at close range. Stay on high walls out of grenade range.', 'Winston dive on Cassidy protects Lucio. Reinhardt shield forces Cassidy to focus elsewhere. Genji duel against Cassidy relieves backline pressure.', '[\"Winston + Lucio dive\",\"Reinhardt + Lucio brawl\"]', '[\"Cassidy + Brigitte lockdown\",\"Cassidy + Orisa poke hold\"]', 2),
(49, 25, 1, 'Ana anti-heal grenade completely shuts down Mauga\'s cardiac overdrive healing passive. His overhealth generation stops under anti-heal. Stay close to teammates, rush Ana before she can grenade, and use Cage Fight ult when you have healing.', 'Kiriko suzu cleanses anti-grenade on Mauga. Moira orb healing partially offsets anti-heal. Lucio speed helps Mauga close gap on Ana.', '[\"Kiriko + Mauga brawl\",\"Lucio + Mauga engage speed\"]', '[\"Ana + Brigitte anti-brawl\",\"Ana + Kiriko sustain\"]', 3),
(50, 25, 35, 'Roadhog hook pulls Mauga out of position or hooks him mid-Overrun charge. His shotgun burst is effective against Mauga\'s large hitbox. Use Cage Fight when Roadhog hooks in to trap him.', 'Sombra hack removes Roadhog hook. Ana anti-heal on Roadhog negates his self-heal. Orisa spear disrupts Roadhog positioning.', '[\"Lucio + Mauga\",\"Kiriko + Mauga brawl\"]', '[\"Roadhog + Reaper brawl\",\"Roadhog + Moira sustain\"]', 2),
(51, 26, 31, 'Pharah completely avoids Mei\'s ice wall and cryo-freeze by flying overhead. Primary fire can\'t reach effective Pharah altitude. Use Blizzard to zone landing spots and request hitscan support.', 'Cassidy, Soldier: 76, or Widowmaker handle Pharah in the air. Hanzo Storm Arrow punishes aerial targets. Ana sleep dart grounds Pharah.', '[\"Mei + Orisa choke hold\",\"Mei + Reinhardt brawl gate\"]', '[\"Pharah + Mercy poke\",\"Pharah + Juno air dominance\"]', 3),
(52, 26, 33, 'Reaper closes on Mei with Wraith Form which ignores slow, and his shotguns delete her fast. Use Cryo-Freeze to survive his initial burst and ice wall to separate him from teammates.', 'Roadhog hook catches Reaper. Brigitte stun stops his engage. High-ground hold denies Reaper ground flanks entirely.', '[\"Mei + Orisa\",\"Mei + Roadhog brawl\"]', '[\"Reaper + Zarya bubble push\",\"Reaper + Junker Queen brawl\"]', 2),
(53, 27, 46, 'Widowmaker one-shots Mercy instantly — she has lowest HP in the game. Constantly guardian angel to a moving target and avoid stationary healing. Pre-emptively switch beam targets to confuse Widow\'s aim.', 'Winston dive on Widow is the standard answer. D.Va fly matrix blocks sniper shots covering Mercy. Another Widowmaker or Hanzo can counter-snipe.', '[\"Pharah + Mercy (force Widow off angle)\",\"D.Va + Mercy\"]', '[\"Widowmaker + Ashe double poke\",\"Widowmaker + Hanzo sniper pair\"]', 3),
(54, 27, 43, 'Tracer blips onto Mercy and bursts her in one clip easily. Mercy can\'t fight back at that range. Guardian Angel to a tank or off-angle teammate to break Tracer\'s follow-up. Call for Brigitte to peel.', 'Brigitte is the premier Tracer answer. Cassidy magnetic grenade deletes Tracer. Kiriko kunai burst punishes Tracer when she targets Mercy.', '[\"Brigitte + Mercy brawl\",\"Orisa + Mercy poke hold\"]', '[\"Tracer + Genji flanker combo\",\"Tracer + Sombra double dive\"]', 3),
(55, 27, 14, 'Genji dash jumps to Mercy\'s elevated position and bursts her quickly. Constantly guardian angel to moving targets and avoid staying in the air too long. Pistol can push him back if desperate.', 'Brigitte stun stops Genji on Mercy. Kiriko teleport saves Mercy. Cassidy grenade tracks Genji to Mercy\'s position.', '[\"Brigitte + Mercy brawl\",\"Orisa + Mercy anchor hold\"]', '[\"Genji + Ana nano blade dive\",\"Genji + Tracer dive combo\"]', 2),
(56, 29, 40, 'Sombra hack disables Moira\'s Fade escape — her only protection tool. A hacked Moira is an easy kill. Group with teammates so they can cover you after hack. Try to throw orbs before getting in hack range.', 'Kiriko suzu cleanses hack on Moira. Wrecking Ball sensor detects Sombra. Winston dive keeps Sombra off the support line.', '[\"Kiriko + Moira double support\",\"Reinhardt + Moira brawl\"]', '[\"Sombra + Tracer backline dive\",\"Sombra EMP + full dive combo\"]', 3),
(57, 29, 31, 'Moira has no reliable long-range ability to contest Pharah. Her orbs travel slowly and can\'t track Pharah. Use Fade to escape Pharah rockets and wait for Pharah to come to ground level.', 'Cassidy or Soldier: 76 handle Pharah. Ana sleep dart grounds Pharah. Roadhog hook punishes low-flying Pharah.', '[\"Moira + Orisa hold\",\"Moira + Reinhardt brawl\"]', '[\"Pharah + Mercy poke\",\"Pharah + Juno air combo\"]', 2),
(58, 30, 33, 'Reaper shreds Orisa up close — his shotguns deal massive damage against her large hitbox and lifesteal sustains him through her poke. Fortify when he engages and use Spear to interrupt his burst window. Keep distance with terrain.', 'Ana anti-heal grenade nullifies Reaper lifesteal. Roadhog hook removes Reaper from the engagement. Brigitte stun stops Reaper\'s short-range burst.', '[\"Orisa + Ana poke\",\"Orisa + Kiriko\"]', '[\"Reaper + Roadhog brawl push\",\"Reaper + Zarya shield brawl\"]', 3),
(59, 30, 40, 'Sombra hack disables Fortify and Javelin Spin — Orisa\'s key defensive tools. A hacked Orisa can be hooked or burst down. Play near teammates to get hack removed quickly.', 'Kiriko suzu cleanses hack on Orisa. Winston dive forces Sombra off. Wrecking Ball sensor detects Sombra.', '[\"Kiriko + Orisa anchor\",\"Ana + Orisa poke\"]', '[\"Sombra + Reaper counter-dive\",\"Sombra EMP + Reaper combo\"]', 2),
(60, 30, 32, 'Ramattra Nemesis form\'s punch blocks bypass Orisa\'s poke and his long-range range in Omnic form threatens her. Fortify his punches and use Spear to slow his Nemesis advance. Don\'t fight him in close quarters.', 'Ana anti-heal grenade limits Ramattra sustain in Nemesis form. Sombra hacks Ramattra to prevent Nemesis switch. Kiriko suzu saves team from Annihilation ult.', '[\"Orisa + Ana poke\",\"Orisa + Sigma long range hold\"]', '[\"Ramattra + Reaper + Ana brawl push\",\"Ramattra + Zarya Annihilation combo\"]', 2),
(61, 31, 39, 'Soldier: 76 is the most reliable Pharah counter — his hitscan with high accuracy destroys Pharah in the air. His sprint lets him reposition under Pharah rockets. Concussive Blast can dodge his Helix Rockets but avoid direct fire.', 'Mercy amplifies Pharah\'s rockets when paired (Pharmercy). Ana sleep dart removes Pharah while you reposition. Lucio speedboost helps Pharah dodge hitscan.', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno air dominance\"]', '[\"Soldier: 76 + Widowmaker double hitscan\",\"Cassidy + Widowmaker poke\"]', 3),
(62, 31, 46, 'Widowmaker one-shots Pharah with a headshot and can track her in the air easily. Fly unpredictably — zig-zag and use Hover Jets to vary altitude. Concussive Blast to change direction rapidly.', 'Mercy damage boost forces Widowmaker off angle. Echo can fly to contest Widow\'s high ground. Winston dive disrupts Widow.', '[\"Pharah + Mercy poke\",\"Pharah + Juno\"]', '[\"Widowmaker + Cassidy double poke\",\"Widowmaker + Soldier: 76\"]', 3),
(63, 31, 7, 'Cassidy Magnetic Grenade can catch Pharah when she dips close to the ground and his hitscan pierces through her rocket barrage. Fly at max altitude to stay above grenade range.', 'Mercy gives Pharah damage boost and damage reduce. Ana sleep dart punishes Cassidy. Juno ring boosts Pharah to escape grenade range.', '[\"Pharah + Mercy\",\"Pharah + Juno + Mercy triple air\"]', '[\"Cassidy + Soldier: 76 dual hitscan\",\"Cassidy + Widowmaker\"]', 2),
(64, 32, 40, 'Sombra hack disables Ramattra\'s Nemesis Form switch and all abilities, removing his primary tank threat. Stay in Omnic form for range if Sombra is nearby and try to Void Barrier to protect yourself until hack expires.', 'Kiriko suzu cleanses hack on Ramattra. Wrecking Ball sensor detects Sombra. Ana nano boost allows Ramattra to brawl through even after hack expires.', '[\"Kiriko + Ramattra brawl\",\"Ana + Ramattra nano\",\"Lucio + Ramattra speed\"]', '[\"Sombra + Tracer double dive\",\"Sombra EMP + full dive combo\"]', 3),
(65, 32, 31, 'Pharah punishes Ramattra in both forms — his Void Barrier doesn\'t protect from above and he has no anti-air tool. Nemesis form is useless against a flying Pharah. Use Annihilation ult to zone the ground fight and request air support.', 'Cassidy or Soldier: 76 handle Pharah. Ana sleep dart drops Pharah. Sigma Kinetic Grasp absorbs Pharah rockets from above.', '[\"Ramattra + Ana brawl\",\"Ramattra + Kiriko sustain\"]', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno air dominance\"]', 2),
(66, 33, 31, 'Pharah is completely out of Reaper\'s range. His shotguns can\'t reach her altitude and Wraith Form doesn\'t help against air attacks. You can only wait out Pharah and use Death Blossom ult to clear the ground fight.', 'Cassidy or Soldier: 76 can counter Pharah for the team. Ana sleep dart grounds her. Roadhog hook punishes Pharah flying low.', '[\"Reaper + Roadhog brawl\",\"Reaper + Zarya brawl\"]', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno aerial combo\"]', 3),
(67, 33, 1, 'Ana anti-heal grenade completely removes Reaper\'s lifesteal passive — his core sustain. A grenaded Reaper loses all his tankiness in a brawl. Fight Ana only through Wraith Form to dodge the grenade.', 'Lucio speed helps Reaper dodge Ana grenades. Kiriko suzu cleanses anti-heal on Reaper. Sombra hacks Ana, disabling sleep dart and grenade.', '[\"Reaper + Lucio speed\",\"Reaper + Kiriko suzu save\"]', '[\"Ana + Brigitte anti-brawl combo\",\"Ana + Kiriko sustain duo\"]', 2),
(68, 33, 35, 'Roadhog hooks Reaper out of Wraith Form entry and his shotgun burst at that range deals comparable damage. Both heroes are brawlers — Roadhog wins because he has more HP and self-heal. Try to flank Roadhog from behind.', 'Ana anti-heal stops Roadhog self-heal. Sombra hacks Roadhog, removing hook. Zarya bubble on Reaper saves him from the hook kill combo.', '[\"Reaper + Ana + Zarya brawl\",\"Reaper + Zarya bubble protect\"]', '[\"Roadhog + Moira healing brawl\",\"Roadhog + Junker Queen brawl\"]', 2),
(69, 34, 31, 'Pharah bombs down on Reinhardt and his shield is angled forward — it doesn\'t cover aerial attacks effectively. Tilt your camera up and angle shield overhead. Fire Strike can reach Pharah if she is low. Request hitscan immediately.', 'Cassidy, Soldier: 76, or Widowmaker cover air threats. Ana sleep dart drops Pharah. Junkrat can zone Pharah with RIP-Tire.', '[\"Reinhardt + Ana brawl\",\"Reinhardt + Kiriko\"]', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno aerial\"]', 3),
(70, 34, 5, 'Bastion Sentry mode destroys Reinhardt\'s shield in seconds. Never stand behind shield against Bastion — retreat and flank. Use Charge to surprise Bastion from off-angle and pin him. Fire Strike through walls to poke.', 'Genji deflect redirects Bastion fire back at him. Sombra hacks Bastion, disabling Sentry. Pharah bombs Bastion position from above.', '[\"Reinhardt + Pharah combo\",\"Reinhardt + Sombra\"]', '[\"Bastion + Orisa + Brigitte anchor hold\",\"Bastion + Reinhardt shield + Mercy\"]', 3),
(71, 34, 40, 'Sombra hack removes Reinhardt\'s shield, charge, and fire strike — all his core tools. A hacked Reinhardt is stuck as a melee hero only. Charge through Sombra to punish her if she appears in front.', 'Kiriko suzu cleanses hack on Reinhardt instantly. Ana sleep dart punishes Sombra before she hacks. Wrecking Ball sensor detects Sombra before engage.', '[\"Reinhardt + Kiriko brawl\",\"Reinhardt + Ana brawl\"]', '[\"Sombra + Reaper backline dive\",\"Sombra EMP + full dive\"]', 2),
(72, 35, 1, 'Ana anti-heal grenade completely stops Roadhog\'s Take a Breather self-heal — his entire survivability kit. Never heal in the open against an Ana. Use Whole Hog or hook Ana directly to eliminate her.', 'Kiriko suzu cleanses anti-heal on Roadhog. Lucio speed helps Roadhog gap-close on Ana. Sombra hacks Ana, removing sleep dart and grenade.', '[\"Roadhog + Kiriko\",\"Roadhog + Lucio speed brawl\"]', '[\"Ana + Brigitte anti-brawl\",\"Ana + Kiriko sustain duo\"]', 3),
(73, 35, 40, 'Sombra hack disables Roadhog\'s hook, breather, and ult — his entire toolkit. A hacked Roadhog is a slow, large target. Hook Sombra before she can get into hack range or position behind cover when she is spotted.', 'Kiriko suzu cleanses hack. Wrecking Ball sensor spots Sombra. Moira fade-orb helps sustain Roadhog after hack expires.', '[\"Roadhog + Kiriko\",\"Roadhog + Moira brawl sustain\"]', '[\"Sombra + Reaper combo dive\",\"Sombra EMP + Tracer double dive\"]', 2),
(74, 35, 30, 'Orisa Javelin Spin prevents Roadhog from hooking her and she can spear him during the hook animation. Her fortify makes her immune to hook displacement. Fight Orisa only when Spear and Fortify are on cooldown.', 'Sombra hacks Orisa, removing Fortify. Zarya bubble on Roadhog during spear saves him. Ana anti-heal on Orisa limits her poke damage sustain.', '[\"Roadhog + Ana\",\"Roadhog + Kiriko brawl\"]', '[\"Orisa + Bastion anchor hold\",\"Orisa + Sigma poke\"]', 2),
(75, 37, 33, 'Reaper\'s close range shotguns bypass Sigma\'s Experimental Barrier and shred him quickly. His Wraith lets him close distance through Kinetic Grasp. Keep Reaper at range using Hyperspheres and avoid close-quarters fights.', 'Roadhog hook removes Reaper from the engagement. Ana anti-heal grenade stops Reaper lifesteal. Brigitte stun peels Reaper off Sigma.', '[\"Sigma + Ana poke\",\"Sigma + Kiriko\"]', '[\"Reaper + Zarya brawl push\",\"Reaper + Roadhog brawl dive\"]', 3),
(76, 37, 31, 'Pharah\'s rockets bypass Sigma\'s barrier from above. Kinetic Grasp can absorb rockets when facing up but the timing is difficult. Use Gravitic Flux to punish Pharah when she is low altitude.', 'Cassidy or Soldier: 76 handle Pharah. Ana sleep dart drops Pharah. Hanzo Storm Arrow punishes aerial movement.', '[\"Sigma + Ana long-range\",\"Sigma + Kiriko poke\"]', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno aerial\"]', 2),
(77, 38, 47, 'Winston leaps onto Sojourn and his bubble blocks her railgun charges. Her slides don\'t escape Winston\'s large tesla cannon arc. Use Disruptor Shot to zone Winston and try to railgun him at close range during his bubble downtime.', 'Roadhog hook interrupts Winston leap. Brigitte stun peels Winston off Sojourn. Ana sleep dart catches Winston mid-dive.', '[\"Sojourn + Orisa anchor\",\"Sojourn + Roadhog brawl\"]', '[\"Winston + Tracer dive\",\"Winston + D.Va double dive\"]', 3),
(78, 38, 10, 'D.Va Defense Matrix eats Sojourn\'s railgun shots — including charged ones. Her matrix windows negate Sojourn\'s burst potential. Slide away when matrix is up and re-engage when matrix is on cooldown.', 'Sombra hacks D.Va, disabling matrix. Zarya bubble on Sojourn protects from D.Va dive. Ana sleep dart prevents Self-Destruct.', '[\"Sojourn + Ana poke\",\"Sojourn + Orisa hold\"]', '[\"D.Va + Winston double dive\",\"D.Va + Genji dive\"]', 2),
(79, 39, 47, 'Winston leaps directly onto Soldier and his bubble blocks hitscan shots completely. Sprint can create distance but Winston closes it fast. Save Helix Rockets for when bubble expires — they deal massive burst damage at point blank.', 'Roadhog hook catches Winston mid-jump. Brigitte stun peels Winston off Soldier. Ana sleep dart stops Winston mid-dive.', '[\"Soldier: 76 + Orisa anchor\",\"Soldier: 76 + Mercy damage boost\"]', '[\"Winston + Tracer dive\",\"Winston + D.Va double dive\"]', 3),
(80, 39, 14, 'Genji deflects Soldier\'s primary fire and Helix Rockets back at him. Don\'t shoot during Deflect — use Sprint to reposition instead. At medium range, Soldier wins if Deflect is on cooldown.', 'Brigitte stun shuts Genji down. Kiriko teleport saves Soldier from Genji burst. Cassidy grenade punishes Genji flanks.', '[\"Soldier: 76 + Brigitte\",\"Soldier: 76 + Orisa hold\"]', '[\"Genji + Ana nano blade\",\"Genji + Tracer double flanker\"]', 2),
(81, 40, 22, 'Kiriko suzu cleanses hacks from the entire team, negating Sombra\'s only offensive tool. Without hack, Sombra\'s pistol DPS is low. Hack Kiriko first before engaging a team fight — she is your top priority target.', 'Any flanker can chase down Sombra once detected. Wrecking Ball sensor detects invis Sombra. Winston can pressure Sombra away from Kiriko.', '[\"Sombra + Tracer double hack dive\",\"Sombra + Winston dive\"]', '[\"Kiriko + Brigitte lockdown\",\"Kiriko + Ana sustain duo\"]', 3),
(82, 40, 7, 'Cassidy\'s Magnetic Grenade can be thrown on Sombra\'s predicted decloak position and his fan the hammer bursts her at close range. She has very low HP. Stay mid-range and bait out her decloak.', 'Wrecking Ball sensor detects Sombra position. Brigitte stun peels Sombra off supports. Kiriko suzu protects targeted teammates from hack burst.', '[\"Sombra + Reaper backline\",\"Sombra EMP + dive\"]', '[\"Cassidy + Brigitte lockdown\",\"Cassidy + Orisa hitscan hold\"]', 2),
(83, 41, 31, 'Symmetra\'s beam and turrets cannot reach Pharah in the air. She has zero anti-air capability. Teleporter can reposition team to escape Pharah pressure. Request a hitscan hero or use Photon Barrier ult to deny ground.', 'Cassidy, Soldier: 76, or Widowmaker handle Pharah. Ana sleep dart grounds Pharah. Roadhog hook punishes low-flying Pharah.', '[\"Symmetra + Reinhardt choke\",\"Symmetra + Orisa hold point\"]', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno air dominance\"]', 3),
(84, 41, 46, 'Widowmaker out-ranges Symmetra completely and one-shots her. Teleporter can move team around sniper sightlines. Place turrets on high-ground routes Widow uses to approach.', 'Winston or Wrecking Ball dive Widow off angle. D.Va fly matrix covers Symmetra from sniper shots. Echo can fly to contest Widow\'s position.', '[\"Symmetra + Reinhardt gate hold\",\"Symmetra + Sigma poke\"]', '[\"Widowmaker + Ashe double poke\",\"Widowmaker + Hanzo sniper\"]', 3),
(85, 41, 33, 'Reaper teleports past Symmetra\'s turrets and deletes her in close range. Her ramp-up beam needs time to charge which Reaper won\'t give her. Place turrets at varying heights to slow his approach.', 'Roadhog hook catches Reaper approach. Brigitte stun stops Reaper at close range. Orisa Fortify + Spear punishes Reaper in the open.', '[\"Symmetra + Orisa choke hold\",\"Symmetra + Roadhog brawl\"]', '[\"Reaper + Zarya brawl push\",\"Reaper + Roadhog dive combo\"]', 3),
(86, 42, 31, 'Pharah bombs Torbjörn\'s turret and him from above angles he cannot effectively target. Turret deals good damage if Pharah dips low. Use Overload ult to give the turret extra HP and request hitscan.', 'Cassidy or Soldier: 76 eliminate Pharah. Ana sleep dart drops Pharah. Hanzo Storm Arrow punishes her aerial movement.', '[\"Torbj\\u00f6rn + Orisa hold\",\"Torbj\\u00f6rn + Bastion anchor brawl\"]', '[\"Pharah + Mercy Pharmercy\",\"Pharah + Juno air dominance\"]', 3),
(87, 42, 46, 'Widowmaker one-shots Torbjörn easily and can destroy his turret from max range. Place turret in a position that covers sniper angles. Rivet Gun at medium range can duel Widow if she isn\'t scoped.', 'Winston dive on Widow. D.Va fly matrix blocks sniper shots to turret. Pharah contests Widow\'s high ground position.', '[\"Torbj\\u00f6rn + Orisa poke hold\",\"Torbj\\u00f6rn + Sigma long-range\"]', '[\"Widowmaker + Ashe double sniper\",\"Double sniper poke\"]', 2),
(88, 42, 48, 'Wrecking Ball destroys Torbjörn\'s turret instantly with Grappling Claw slam and his high mobility prevents Torbjörn from setting up again. Throw turret far from the objective to buy time and use Overload to survive.', 'Ana sleep dart catches Wrecking Ball after a slam. Roadhog hook grabs Wrecking Ball. Junkrat mines zone Ball\'s slam entry paths.', '[\"Torbj\\u00f6rn + Orisa hold\",\"Torbj\\u00f6rn + Junkrat zone trap\"]', '[\"Wrecking Ball + Winston double dive\",\"Wrecking Ball + Sombra EMP\"]', 3),
(89, 43, 6, 'Brigitte Shield Bash stuns Tracer mid-blink and her inspire healing counters Tracer burst. Never attack a Brigitte alone. Use Pulse Bomb on Brigitte when she overextends but avoid her stun range entirely.', 'Lucio speedboost extends Tracer\'s reach past Brigitte. Ana sleep dart helps if Tracer is hounded. Sombra hack on Brigitte removes her shield bash briefly.', '[\"Tracer + Genji double dive\",\"Tracer + Sombra hack dive\"]', '[\"Brigitte + Orisa brawl hold\",\"Brigitte + Cassidy lockdown\"]', 3),
(90, 43, 7, 'Cassidy\'s Magnetic Grenade attaches to Tracer and deals burst damage through blinks. His fan the hammer also punishes blink entry. Use Recall to rewind grenade damage and bait out grenade before engaging.', 'Lucio speedboost helps Tracer escape grenade range. Kiriko suzu cleanses grenade damage effect. Winston dive on Cassidy removes him before he can grenade.', '[\"Tracer + Winston dive\",\"Tracer + Lucio speed\"]', '[\"Cassidy + Brigitte double lockdown\",\"Cassidy + Orisa poke\"]', 2),
(91, 43, 29, 'Moira\'s biotic orb latches onto Tracer through blinks and her Fade can disengage when Tracer commits. Her sustained healing and grasp drain match Tracer\'s burst. Use Recall to refresh HP and burst Moira at sub-5m range.', 'Kiriko teleport assists Tracer in escaping Moira drain. Sombra hack removes Moira\'s Fade. Any high-burst hero deletes Moira before she can sustain through Tracer.', '[\"Tracer + Genji dive\",\"Tracer + Sombra double dive\"]', '[\"Moira + Brigitte brawl sustain\",\"Moira + Roadhog sustain\"]', 2),
(92, 46, 47, 'Winston\'s leap travels the entire map vertically and his bubble prevents Widowmaker from shooting back. Grapple to high ground as soon as you hear his leap. Widow cannot fight Winston at close range — escape immediately.', 'D.Va Defense Matrix can block Winston leap landing. Roadhog hook catches Winston when he dives Widow. Ana sleep dart stops Winston mid-dive.', '[\"Widowmaker + D.Va\",\"Widowmaker + Roadhog peel\"]', '[\"Winston + D.Va double dive\",\"Winston + Tracer dive\"]', 3),
(93, 46, 10, 'D.Va fly matrix eats Widowmaker\'s fully-charged shots — the exact shots that make her dangerous. Time your shots for matrix downtime. Grapple to high angles where D.Va\'s matrix arc can\'t reach.', 'Roadhog hooks D.Va when she flies close. Ana sleep dart stops D.Va bomb. Pharah can contest D.Va\'s air control.', '[\"Widowmaker + Roadhog peel\",\"Widowmaker + Ana poke\"]', '[\"D.Va + Winston double dive\",\"D.Va + Tracer dive cover\"]', 2),
(94, 46, 40, 'Sombra hack disables Widowmaker\'s Grappling Hook — her only escape. A hacked Widow is a sitting target with a slow bolt rifle. Hack cooldown window is the most dangerous moment. Stay near ledge drops to escape without grapple.', 'Kiriko suzu cleanses hack on Widowmaker. Wrecking Ball sensor detects Sombra approach. Roadhog can peel Sombra off Widow.', '[\"Widowmaker + Kiriko\",\"Widowmaker + Roadhog + Ana poke\"]', '[\"Sombra + Tracer double backline dive\",\"Sombra EMP + full dive\"]', 2),
(95, 47, 50, 'Zarya\'s bubble charges on every Winston tesla cannon shot, making him power up his hardest counter. Her beam melts Winston through his bubble. Never shoot into a Zarya bubble. Save bubble for defensive use and look for other targets.', 'Ana anti-grenade limits Zarya sustain. Sombra hacks Zarya\'s bubble off. Roadhog hook removes Zarya from position before she reaches high energy.', '[\"Winston + Ana dive\",\"Winston + Sombra hack dive\"]', '[\"Zarya + Reaper brawl\",\"Zarya + Graviton + Hanzo combo\"]', 3),
(96, 47, 33, 'Reaper\'s shotguns destroy Winston\'s relatively low HP pool fast and his lifesteal outheals Winston\'s tesla damage. Avoid diving into a Reaper without bubble. Use Primal Rage to escape if Reaper corners you.', 'Ana anti-heal grenade stops Reaper lifesteal. Kiriko suzu saves Winston from burst. Brigitte stun peels Reaper off Winston after a dive.', '[\"Winston + Ana dive\",\"Winston + Kiriko dive\"]', '[\"Reaper + Zarya brawl\",\"Reaper + Roadhog sustain brawl\"]', 3),
(97, 48, 40, 'Sombra hack disables all of Wrecking Ball\'s mobility — Grappling Claw, Minefield, and Roll mode. A hacked Ball is stuck in Walker form with no escape. Drop mines before entering a zone where Sombra is suspected.', 'Kiriko suzu cleanses hack on Wrecking Ball instantly. Ana sleep dart pins Sombra before hack. Wrecking Ball\'s own sensors ironically help detect Sombra approach.', '[\"Wrecking Ball + Kiriko dive\",\"Wrecking Ball + Ana dive\"]', '[\"Sombra + Reaper counter-dive\",\"Sombra EMP + full dive combo\"]', 3),
(98, 48, 1, 'Ana sleep dart catches Wrecking Ball mid-swing and her anti-heal grenade prevents his passive HP regeneration. Stay unpredictable with swing paths to dodge sleep dart. Use Adaptive Shield frequently to build HP before she grenades.', 'Kiriko suzu cleanses anti-heal on Ball. Lucio speedboost covers Ball\'s disengages. Moira orb healing offsets anti-heal somewhat.', '[\"Wrecking Ball + Kiriko\",\"Wrecking Ball + Lucio speed\"]', '[\"Ana + Kiriko sustain anti-dive\",\"Ana + Brigitte anti-dive hold\"]', 2),
(99, 50, 40, 'Sombra hack disables Zarya\'s bubbles entirely — her only source of energy and protection. A de-bubbled low-energy Zarya is much easier to kill. Hack Zarya right before a fight starts to remove her peak damage potential.', 'Kiriko suzu cleanses hack on Zarya. Wrecking Ball sensor detects Sombra. Winston dive keeps Sombra from reaching Zarya\'s backline.', '[\"Zarya + Ana Graviton combo\",\"Zarya + Reaper brawl\"]', '[\"Sombra + Tracer double dive hack\",\"Sombra EMP + full dive combo\"]', 3),
(100, 50, 1, 'Ana anti-heal grenade prevents Zarya from regenerating HP between bubbles. Her high damage also brings Zarya\'s HP down during the non-bubble window. Sleep dart can interrupt Graviton Surge if timed perfectly.', 'Kiriko suzu cleanses anti-grenade on Zarya. Moira orb partially offsets anti-heal. Lucio speedboost helps Zarya disengage from Ana sightlines.', '[\"Zarya + Reaper brawl\",\"Zarya + Graviton + Kiriko\"]', '[\"Ana + Kiriko sustain anti-dive\",\"Ana + Brigitte anti-brawl combo\"]', 2),
(101, 50, 35, 'Roadhog hook grabs Zarya when she has no bubbles and his shotgun burst deals massive damage. Time the hook between bubble cooldowns. Graviton Surge traps both Roadhog and teammates — save it for grouped enemies.', 'Sombra hacks Roadhog, removing his hook. Ana anti-heal negates Roadhog self-heal. Kiriko suzu saves Zarya from hook kill combo.', '[\"Zarya + Ana Graviton\",\"Zarya + Reaper + Ana brawl\"]', '[\"Roadhog + Reaper brawl\",\"Roadhog + Moira sustain brawl\"]', 2),
(102, 51, 43, 'Tracer deletes Zenyatta\'s 225 HP in one clip easily. He has no mobility tools. Use Transcendence ult to survive a Pulse Bomb if timed right. Position far behind tanks and rely on teammates for peel.', 'Brigitte hard counters Tracer. Cassidy magnetic grenade kills Tracer. Kiriko teleport saves Zenyatta from flanks.', '[\"Zenyatta + Brigitte brawl\",\"Zenyatta + Orisa anchor hold\"]', '[\"Tracer + Genji double dive\",\"Tracer + Sombra backline\"]', 3),
(103, 51, 46, 'Widowmaker one-shots Zenyatta easily — he has the lowest effective HP among supports. Never hold a sightline near a Widowmaker. Keep Discord orb on Widow to help teammates kill her.', 'Winston dive on Widow is essential. D.Va fly matrix covers Zenyatta from sniper fire. Echo fly-duel against Widow helps.', '[\"Zenyatta + Winston + D.Va dive\",\"Zenyatta + Orisa hold\"]', '[\"Widowmaker + Ashe double sniper\",\"Widowmaker + Hanzo sniper pair\"]', 3),
(104, 51, 14, 'Genji dashes onto Zenyatta and burst-combos him before he can orb-react. Use Orb of Discord on Genji and throw primary fire as he approaches to deal chip damage. Transcendence can save you from nano blade but not regular Genji burst.', 'Brigitte stun stops Genji on Zenyatta. Kiriko teleport saves Zenyatta from Genji. Roadhog hook catches Genji mid-dash.', '[\"Zenyatta + Brigitte brawl\",\"Zenyatta + Reinhardt hold\"]', '[\"Genji + Ana nano blade\",\"Genji + Tracer dive combo\"]', 2);
INSERT INTO `counter_notes` (`noteID`, `heroID`, `userID`, `noteText`, `isPublic`, `createdAt`, `counterTips`, `teammateHelp`, `goodComps`, `dangerousComps`, `severity`, `counteredByHeroID`) VALUES
(18, 1, 6, '', 1, '2026-06-16 05:54:20', 'asasdf', 'asdfasdf', '[\"sadf\",\"asdf\"]', '[\"asdf\",\"qsdf\"]', 1, 5);
INSERT INTO `heroes` (`name`, `role`, `portrait`, `description`, `abilities`, `screenshot`, `heroID`, `best_maps`) VALUES
('Ana', 'support', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/985b06beae46b7ba3ca87d1512d0fc62ca7f206ceca58ef16fc44d43a1cc84ed.png', 'One of the founding members of Overwatch, Ana uses her skills and expertise to defend her home and the people she cares for.', '[{\"name\":\"Biotic Rifle\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/db33c39f25d96a2cabcacb778cf784535279180f6d9119ef56311bdcdf6077df.png\"},{\"name\":\"Sleep Dart\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/620a97282b81ea178951b565e8249361e67c868387e61a4297261ffa11bace13.png\"},{\"name\":\"Biotic Grenade\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/886454bdb7df9ad8a47c4a3a8fa5dd488f5b2996e311f16d42a5f022942c4d18.png\"},{\"name\":\"Nano Boost\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/726f2fa5b149e5ac58310f11893db1850a7312270db4f88c164bb43a84f962cf.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt76ab9c7b4d291756/631a8bab636d390da7825df5/2600_Ana.jpg', 1, '[\"King\'s Row\",\"Eichenwalde\",\"Hanamura\"]'),
('Anran', 'damage', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/2c38b41d79a1ce9a08b9ad8eb7edf3ff819bd448af16a5815be8c7fdb7203aa0.png', 'The star graduate of Wuxing University’s Fire College, Anran is always burning to push her limits.', '[{\"name\":\"Zhuque Fans\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/b575eb7daebdb64b81b0942c466b00117b31925678d10ab8739781e0ccf1bd69.png\"},{\"name\":\"Fan the Flames\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/66ed3af8219952edc022c4ef08c65191cdd6839aae0a2c451f70f8f61d2bc7de.png\"},{\"name\":\"Dancing Blaze\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/c8a106a2acae1b9edf47495af102cf17fd7e8320c76b201d533f5723afc45d14.png\"},{\"name\":\"Inferno Rush\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/92cd63b84d95581dfbe8c3974be31c9f303db4d25bfd117474f93ab5bc9cca4b.png\"},{\"name\":\"Vermillion Ascent\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/a7f971f4e0c7c898e634d0787f4a0da48ae78b7adbdc7b71149efa0352319c76.png\"},{\"name\":\"Vermillion Revival\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/9060d9e2e407a31ab95948e6512373a4318ebd8883aefa91e9f2fa9bbffb7076.png\"},{\"name\":\"Ignition\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/f4a70d5', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt9b7863b08388e81f/69d6e0fa369d00815f7d8ccc/2600_Anran.png', 2, NULL),
('Ashe', 'damage', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/4076bbaa2eb52a0bfe612434071e56e7702d5454473dbbea2f9e392a9d997a94.png', 'Ashe is the ambitious and calculating leader of the Deadlock Rebels Gang and a respected figure in the criminal underworld.', '[{\"name\":\"The Viper\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/1e5c0d3360d2357d28d4c5eacb6727589ac3d4ca99b09e3f8fd67846b6b2ef4e.png\"},{\"name\":\"Coach Gun\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/834538cfbc7c2eb7f9fd18aea7ba91264446af706199d716526060e6e34b48ed.png\"},{\"name\":\"Dynamite\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/0e2cc18253fc824f3eac3df4623dfb03210937e27901cc868a8694a4a65e68ad.png\"},{\"name\":\"B.O.B.\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/224dd7fd039ee71e2633520cac81186fddabe4d399a64650263514829b936295.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt3fc10a3baca12db5/631a8ba0a633280e74dc25cd/2600_Ashe.jpg', 3, '[\"Circuit Royal\",\"Havana\",\"Junkertown\"]'),
('Baptiste', 'support', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/d4e6f1ca45d9f88fa89260787397f141a6f007b14e5b26698883b6a17bab9680.png', 'An elite combat medic and ex-Talon operative, Baptiste now uses his skills to help those whose lives have been impacted by war.', '[{\"name\":\"Biotic Launcher\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/3c6e635c598b687805163bd2173624d18e3c989ca3c0f7b37e7dadd5179a59c1.png\"},{\"name\":\"Regenerative Burst\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/995d4c830cd4d6d458333a645561fefb75aab4f5228fe6b7923ea55b29f0496d.png\"},{\"name\":\"Immortality Field\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/8e586114b79ae8281255d8e5a5a48d3a855be6e88b3d7abeda93288f4fffe909.png\"},{\"name\":\"Amplification Matrix\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/35311fd3b5a6bdd90d9e58101685675e0ee3562b2d63eb0c5775dd1f7b86cc3b.png\"},{\"name\":\"Exo Boots\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/b3451a608be2eea1a38669721c9cd96ef9114172cec10b06c27e8048f42614bd.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt5ef4dacade9780da/631a8b99e337fa0dc7263be7/2600_Baptiste.jpg', 4, '[\"Rialto\",\"Havana\",\"Circuit Royal\"]'),
('Bastion', 'damage', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/4ede795c2a681aaccfa72d0c901cba0cb8a2c292fd6a97b2ba9faed161c2d184.png', 'Once a frontline combatant in the devastating Omnic Crisis, this curious Bastion unit now explores the world, fascinated by nature but wary of a fearful humanity.', '[{\"name\":\"Configuration: Assault\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/c3391c7eb4ce0ac2483d1821299fa684072e2ace043ac6ae7839f81f09c187f9.png\"},{\"name\":\"Configuration: Recon\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/9febc039b8d8f7743539e8743f78b15495e3ea619615ab763dc747acd29b9615.png\"},{\"name\":\"A-36 Tactical Grenade\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/80deb4f0bd0d41f4f9747c3728e31758dee523821abded024b6c242c659ff454.png\"},{\"name\":\"Reconfigure\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/eb87350ce8e74c06df5b7fb33cfc2904cbb918777d3740f9e0ee87ff5260265f.png\"},{\"name\":\"Configuration: Artillery\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/891396b354d31ef404bf525651f8f95048da8f8816a381021ce8d6e8ccabfafa.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/bltac77c0e793cedb9d/631a8b923ab6f40dd2a906b1/2600_Bastion.jpg', 5, '[\"King\'s Row\",\"Eichenwalde\",\"Midtown\"]'),
('Brigitte', 'support', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/795fba91376d87d441a7f359ae12a3175dfa95825ccc4414cc6b95b129fc4cb0.png', 'No longer sitting on the sidelines, Brigitte Lindholm has taken up arms to defend those in need of protection.', '[{\"name\":\"Rocket Flail\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/e75775c837abbf4aa1ec944fb08f3978819699a27242c64e27f3d52201dee5dc.png\"},{\"name\":\"Repair Pack\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/6a2c40a4d0a87dfb1d07dada2a3aa4bc46e8361e76f10294585fcb28008903b8.png\"},{\"name\":\"Whip Shot\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/b1f72a2f8c1c8df901af39ec7fa33ab69d79c8b92d7bf3319e4a2081e4712dac.png\"},{\"name\":\"Barrier Shield\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/d90077573a1495f77345c56ea9231366bac05d3750053e26ccf0b733225ea4c1.png\"},{\"name\":\"Shield Bash\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/da7bcc6cd41e74adbe68450d5afc7809745717e8bdac3fd9cba22f12d6419297.png\"},{\"name\":\"Rally\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/28664c18171b484aefc61836b34d749dac8971f1393c6a17c88ccb60b8c2d0b3.png\"},{\"name\":\"Inspire\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/2d239f8ca1265f4c5f7be415edc5568', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt985b7156ca9b6e62/631a8b7f5f39a30d9cedbacc/2600_Brigitte.jpg', 6, '[\"Eichenwalde\",\"King\'s Row\",\"Midtown\"]'),
('Cassidy', 'damage', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/9240cd64cc8ef58df9acbf55204ab1b5d8578f743fda5931f0dbccbd75ab841b.png', 'Armed with his Peacekeeper revolver, the outlaw Cole Cassidy doles out justice on his own terms.', '[{\"name\":\"Peacekeeper\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/96aadaed5019913a61810e895d9c17d38d369f7c3a3213ced78ef562147a83a5.png\"},{\"name\":\"Combat Roll\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/b22144e644a4a63963e063fc8cc969cfb9061e29993d713b0c64a89b1ac9f280.png\"},{\"name\":\"Deadeye\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/6b78a5cb96040a70e6b41e767a6ea59c2af4e773521b8b4e0bf2c6fd642a3824.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt4bb4c31f6849c25b/631a8b781613910e6926bfd4/2600_Cassidy.jpg', 7, '[\"Havana\",\"Circuit Royal\",\"Rialto\"]'),
('Domina', 'tank', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/1161c112292c56c052c0ae711792fcde06e3251b98bc9709e582dd7585b5dcd6.png', 'As Vishkar Corporation’s most prized negotiator, Domina uses her masterful command of hard-light to take control of every situation.', '[{\"name\":\"Photon Magnum\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/6a661b5275bfbc67f584a80c080b17b7cb4d91d665294b9bbb364e9bcf31812b.png\"},{\"name\":\"Barrier Array\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/909e0bb235934d7961a51fe41f90fadafaee33784b8199f62c92f3dd946da76f.png\"},{\"name\":\"Sonic Repulsors\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/7f54ab0fa0be464fe670b61ee5665e5b3b562909f2e9afa7ad1b95e568e91b1f.png\"},{\"name\":\"Crystal Charge\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/e2a15136441c63461f9c187e39d902fd64710aebc7e87d8430839cc083ca9b45.png\"},{\"name\":\"Panopticon\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/5685ed099de9b6438a493e6060d692bd10ce08424cff88a767dc5b13a7edcb5e.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt5522a118520166f8/6981752246798a3f5135fce2/2600_Domina.png', 8, NULL),
('Doomfist', 'tank', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/ff5c54f43ad253c7faeda9c4ed31d42582ea6b19205d197866f3dd0c0aa14c16.png', 'Doomfist was the calculating leader of Talon, a terrorist organization and paramilitary force that works in direct opposition to Overwatch.', '[{\"name\":\"Hand Cannon\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/3b3a99fadfbd19067a787782d7152ae500ada480f40ae773b9c6d5f8909dd80f.png\"},{\"name\":\"Rocket Punch\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/79fa2ac1beeaaecc23735e2bc41068a99838c76ff626a12ac07fcdc5efd70bd9.png\"},{\"name\":\"Seismic Slam\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/4bc170a43b0d19921079fefcf16e66d720019271e37303413971b12e0ced9eca.png\"},{\"name\":\"Power Block\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/2af34b2442543da4b3a588ae8791c2b9f8a24cf5e17c935f146a7c88b0d02bd4.png\"},{\"name\":\"Meteor Strike\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/dd68ed0cdc85d2bd688a487dc0778cd64e7dc1d11f8e4d5e7bbf421fb1144315.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blteaa58e824d1fc399/631a8b6b0e1b4f0e7b89a538/2600_Doomfist.jpg', 9, '[\"Eichenwalde\",\"King\'s Row\",\"Midtown\"]'),
('D.Va', 'tank', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/df5a5532862d9292634fb3dc0e51a4705aa601de65e5e815513ccc663d84de56.png', 'D.Va is a former professional gamer who now uses her skills to pilot a state-of-the-art mech in defense of her homeland.', '[{\"name\":\"Fusion Cannons\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/1b8dd81bd8353ce0a66009578dc4d7b6a51464e5bc7898010053ff46159f4fa1.png\"},{\"name\":\"Light Gun\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/969a72050f376bf6ee5ed5550a8033cdd661f2f9883c1229e9ee70dd3ae58ec4.png\"},{\"name\":\"Boosters\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/7076c739fe2c1d11f4f118d9e22a3d8f66303242434b71a7e4451e62f5d27b65.png\"},{\"name\":\"Defense Matrix\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/e3806878b38cbab585c4d48e05f2dd63817a36a4f69cedbaf62fd3af6ca5bbd2.png\"},{\"name\":\"Micro Missiles\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/adcd1c898f2ab66779554711451303ee83ca15b70a0951e18964520f5f02566a.png\"},{\"name\":\"Self-Destruct\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/3ae91694dd2901ced5b3c6789b686fbda4175f807abe602101df6a26bfdf3491.png\"},{\"name\":\"Call Mech\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/7117851e322ccefb98a', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/bltcd4bcf30a5794639/631a8b65f581050de0035df6/2600_Dva.jpg', 10, '[\"Busan\",\"Ilios\",\"Lijiang Tower\"]'),
('Echo', 'damage', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/d4f2d5b0c2b7e82d61353186c5f23152ccba9d3569b50839aa580dca3e9114ba.png', 'Echo is a multirole, adaptive robot with the most sophisticated artificial intelligence in the world, originally designed by Dr. Mina Liao for use during combat missions with Overwatch.', '[{\"name\":\"Tri-Shot\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/eda680580d3957d2c06b3006fbe0f0b2f7637a3931c05a266a357984587e4f9f.png\"},{\"name\":\"Sticky Bombs\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/5dd1a8e7c4097e3822db4a36d6bb5277203da4ba6bfd1ebe5ecab0311d199dbc.png\"},{\"name\":\"Flight\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/edbca7879024d5b35a24e942ee5ebdec9780a425ef5e8d64f8113f7d5f2048b3.png\"},{\"name\":\"Focusing Beam\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/864e210890c8ac666d29fdda118a2a8c0ae16fc5471812ef4da4ab322d11bb8e.png\"},{\"name\":\"Duplicate\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/d374c55bb34248543dc4b63b73738fd17a488afa29eaa63f800008edda7f3907.png\"},{\"name\":\"Glide\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/4668bf556984868ba73b931a45fa61bae503f7c67371f1a4f8085c8f992cd6bd.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/blt6a6dc9da49d17b95/631a8b5feef3ae0e03c743ae/2600_Echo.jpg', 11, '[\"Busan\",\"Ilios\",\"Lijiang Tower\"]'),
('Emre', 'damage', 'https://d15f34w2p8l1cc.cloudfront.net/overwatch/c51e2f698138861c0e3b6cfab3c3ca9d67fd709be175e7c397aa6f2649712a30.png', 'Emre disappeared after a lauded tenure on the Overwatch strike team. He has resurfaced years later, his body and mind manipulated by something unknown.', '[{\"name\":\"Synthetic Burst Rifle\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/6db52d088dd5272c7b6aca53746b68a0f6ea7ad23a2ee8143c11d495d602f64b.png\"},{\"name\":\"Cyber Frag\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/58eeb3950828ceadc16565163bfc03231a0cecdf3a0a6ce78de34bdff4bf09bf.png\"},{\"name\":\"Override Protocol\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/fc8088a2968e2850ef438645fd2286ea7abe1779b2eae5cf85638168736ecddc.png\"},{\"name\":\"Altered Vitals\",\"icon\":\"https:\\/\\/d15f34w2p8l1cc.cloudfront.net\\/overwatch\\/fec616f100308698fe85eb6c7a36daa8af6d26181de8fa2f0e59ee2414bcb6df.png\"}]', 'https://blz-contentstack-images.akamaized.net/v3/assets/blt2477dcaf4ebd440c/bltb3519446b8ce60de/698cfe5dfa5dc9748c88fc81/2600_Emre.png', 12, NULL),
